'use strict';
const {Game,NODES,node,LINES,LINE_NAMES,CHARACTERS,FILES,CARDS,BUILDINGS,ICONS}=Yut;
const app=document.querySelector('#app'),QA=new URLSearchParams(location.search).has('qa'),SAVE=QA?'goeul-yut-qa-v11':'goeul-yut-v11';
let game=null,activeSlot=0,selected=null,paused=false,busy=false,timer=null,epoch=0,bet=10;
let config=[{name:'나의 고을',team:0,ai:false,character:0},{name:'청단 대감',team:1,ai:true,character:2},{name:'홍단 마님',team:0,ai:true,character:3},{name:'청단 마님',team:1,ai:true,character:7}];
const money=v=>Math.floor(v).toLocaleString('ko-KR'),img=c=>'assets/characters/'+FILES[c]+'.png';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const team=t=>t===0?'홍단':'청단';
function saved(){try{let s=JSON.parse(localStorage.getItem(SAVE)||!QA&&localStorage.getItem('goeul-yut-v9')||!QA&&localStorage.getItem('goeul-yut-v8')||!QA&&localStorage.getItem('goeul-yut-v7')||!QA&&localStorage.getItem('goeul-yut-v6'));return [6,7,8,9,10,11].includes(s?.version)?s:null}catch{return null}}
function persist(){if(window.NET)return;try{if(game)localStorage.setItem(SAVE,JSON.stringify(game.s));}catch{toast('이 브라우저에서는 자동 저장을 사용할 수 없습니다.')}}
function toast(text){let el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2500)}
function clearRun(){cancelCharge();clearTimeout(timer);epoch++;busy=false;}
function setup(){clearRun();game=null;if(NET.data?.room)NET.call('leave').catch(e=>toast(e.message));else renderLobby();}
function renderSetup(){renderLobby();}
function start(){if(config.filter(p=>p.team===0).length!==2){toast('홍단·청단 팀에 두 명씩 배정해주세요.');return}if(config.every(p=>p.ai)){toast('사람을 한 명 이상 선택해주세요.');return}config.forEach((p,i)=>p.name=p.name.trim()||'양반 '+(i+1));game=new Game(config);paused=false;selected=null;document.querySelector('#reset-btn').hidden=false;render();}
function eligible(id){let s=game.s;if(!NET.canAct()||busy)return false;if(s.phase==='debt')return game.saleOptions().some(o=>o.id===id);if(s.phase==='travel')return id!==game.p.pos;if(s.phase==='route')return s.choice.options.includes(id);if(s.phase==='choice'&&['boost','inspect','invest'].includes(s.choice.kind))return s.choice.options.includes(id);return false}
function playerPanel(p){return `<article class="player owner-${p.color||'red'} team${p.team} ${game.p.id===p.id?'current':''} ${p.out?'out':''}"><img src="${img(p.character)}" alt="${CHARACTERS[p.character]}"><div><span class="team-label t${p.team}">${team(p.team)} 팀 ${p.ai?'· AI':''} ${p.exile?'· 유배 '+p.exile+'회':''} ${p.out?'· 파산':''}</span><div class="name">${esc(p.name)}</div><div class="money">${money(p.cash)} <small>엽전</small></div><small>총자산 ${money(game.assets(p))} · 복귀 ${p.laps||0}회 · 건설 ${game.maxBuild(p)}단계 · 전당포 ${p.pawnUsed?'사용':'미사용'}</small>${p.famine||p.taxAt!==null?'<br><small class="warning">'+(p.famine?'다음 지원금 50엽전 ':'')+(p.taxAt!==null?'가렴주구 대기':'')+'</small>':''}</div></article>`;}
function board(){let s=game.s;return `<div class="board-shell">${boardPicking()&&NET.canAct()?`<div class="selection-banner" role="status"><b>${s.phase==='debt'?'매각할 고을을 선택하세요':s.phase==='travel'?'마굿간 이동 목적지를 선택하세요':s.phase==='route'?'다음 길을 선택하세요':s.choice.kind==='invest'?'무료로 건설할 팀 고을을 선택하세요':s.choice.kind==='inspect'?'건물을 매각할 상대 고을을 선택하세요':'통행료를 높일 팀 고을을 선택하세요'}</b><small>빛나는 칸을 직접 누르세요.${s.phase==='debt'?' 선택한 고을을 다시 누르면 해제됩니다.':''}</small></div>`:''}<div class="board-scroll"><div class="board"><svg class="routes" viewBox="0 0 100 100" aria-hidden="true"><path class="under" d="M90 90V10H10V90Z M90 10L10 90 M10 10L90 90"/><path class="path" d="M90 90V10H10V90Z M90 10L10 90 M10 10L90 90"/></svg>${NODES.map(n=>{let l=s.land[n.id],owner=l?.owner!==null&&l?.owner!==undefined?s.players[l.owner]:null,ps=s.players.filter(p=>!p.out&&p.pos===n.id);return `<button class="node ${n.type!=='property'?'special':''} ${n.type==='inspector'?'inspector':''} ${owner?'team'+owner.team+' owner-'+owner.color:''} ${eligible(n.id)?'eligible':''} ${justBuilt===n.id?'just-built':''} ${saleSelection.has(n.id)&&s.phase==='debt'?'sale-selected':''} ${l?.boost?'boost':''} ${l?.mortgageTurns?'mortgaged':''}" style="left:${n.x}%;top:${n.y}%" data-node="${n.id}" aria-label="${n.name}${owner?' '+esc(owner.name)+' 소유 '+(l.buildings.map(t=>BUILDINGS[t]).join(' · ')||'빈 땅'):''}" ${busy?'disabled':''}>${n.type==='property'&&owner&&l.buildings.length?`<span class="estate-buildings">${l.buildings.map(t=>`<img class="building b${t}" src="assets/buildings/${owner.team===0?'red':'blue'}-${t}.png" alt="${team(owner.team)} ${BUILDINGS[t]}">`).join('')}</span>`:`<span class="nicon">${ICONS[n.type]}</span>`}<span class="nname">${n.name}</span><span class="nvalue">${n.type==='property'?(owner?'통행료 '+game.toll(n.id):n.price+'엽전'):(n.id==='O0'?'+100':'')}</span>${ps.length?`<span class="tokens">${ps.map(p=>`<span class="token owner-${p.color} t${p.team}" data-pid="${p.id}"><img src="${img(p.character)}" alt="${esc(p.name)}의 말"><b>${esc(p.name)}</b></span>`).join('')}</span>`:''}</button>`}).join('')}</div></div><div class="board-footer"><div class="legend"><span><i class="dot"></i>홍단 ${money(game.teamAssets(0))}</span><span><i class="dot t1"></i>청단 ${money(game.teamAssets(1))}</span></div><span>고을을 누르면 정보 확인</span></div></div>`;}
function btn(action,text,kind='primary',value){return `<button class="${kind} full" data-action="${action}" ${value!==undefined?'data-value="'+esc(value)+'"':''} ${busy?'disabled':''}>${text}</button>`}
function targets(){return '<p class="board-pick-note">보드에서 빛나는 고을을 직접 누르세요.</p>'; }
function controls(){let s=game.s,p=game.actor;if(!NET.canAct())return '<p>'+esc(p.name)+(p.ai?' · AI 진행 중입니다.':'님의 선택을 기다리고 있습니다.')+'</p><p class="muted">다른 사용자는 진행 상황을 함께 볼 수 있습니다.</p>'+(['notice','choice','exile','debt'].includes(s.phase)?'<button class="secondary full" data-net="leave">방 나가기</button>':'');if(s.phase==='ended')return '';if(p.ai)return (s.phase==='notice'?'<p>'+esc(s.notice.text)+'</p>':'')+`<div class="auto-status">${paused?'AI가 쉬고 있습니다.':'AI 양반이 다음 수를 생각하고 있어요…'}</div><button class="secondary full" data-do="pause">${paused?'AI 진행 재개':'AI 잠시 멈추기'}</button>`;switch(s.phase){case'notice':return '<p>'+esc(s.notice.text)+'</p>'+btn('ack','확인');case'roll':return powerButton('roll','윷 두 번 던지기');case'moves':return '<p>사용할 윷과 예상 도착지를 선택하세요.<br>모든 이동 후 마지막 칸의 효과만 적용됩니다.</p>'+game.remaining().map(r=>{const targets=game.preview(r.index).map(v=>node(v.at).name);return `<button class="result-choice" data-action="use" data-value="${r.index}" data-preview="${r.index}" ${busy?'disabled':''}><b>${r.name} ${r.value>0?'+':''}${r.value}칸</b><span>→ ${[...new Set(targets)].join(' / ')}</span><small>${targets.length>1?'갈림길에서 경로 선택':game.remaining().length>1?'중간 도착 · 칸 효과 없음':'최종 도착 · 칸 효과 적용'}</small></button>`}).join('');case'extra':return `<p>윷·모가 나왔습니다. 한 번만 더 던질 수 있어요.</p>${powerButton('extra','한 번 더 던지기',true)}${btn('extra','추가 없이 결과 선택','secondary',false)}`;case'route':return `<p>갈림길에 정확히 도착했습니다.<br>선택한 윷 결과의 경로를 고르세요.</p>${s.choice.options.map(id=>btn('route',(/^O/.test(id)?'외곽 길':id==='SE1'?'출발점 지름길':id==='SW1'?'기존 대각선 길':'중앙 지름길')+' → '+node(game.path(s.pendingMove,id).at).name,'secondary',id)).join('')}`;case'travel':return `<p>마굿간 자유 이동입니다.<br>보드의 원하는 칸을 누르세요.<br>안내된 전진 경로가 출발점을 지나면<br>100엽전과 건설 단계 해금을 받습니다.</p>`;case'exile':return (p.cards.includes('pardon')?btn('card','임금의 사면령으로 즉시 탈출','primary',p.cards.indexOf('pardon')):'')+`<p>유배 중 · 남은 휴식 ${p.exile}회<br>윷·모를 던지면 탈출할 수 있습니다.</p>${p.cash>=10?btn('exilePay','속전 10엽전 내고 탈출'):''}${powerButton('exileRoll','윷 한 번으로 탈출 시도')}`;case'debt':return debtPanel();case'choice':{let c=s.choice;if(c.kind==='keep')return '<p>복주머니는 한 장만 보유할 수 있습니다.<br>남길 카드를 선택하세요. 다른 카드는 복주머니로 돌아갑니다.</p><p><b>기존: '+CARDS[p.cards[0]].name+'</b><br>'+CARDS[p.cards[0]].text+'<br><b>새 카드: '+CARDS[c.incoming].name+'</b><br>'+CARDS[c.incoming].text+'</p>'+btn('choose','기존 카드: '+CARDS[p.cards[0]].name,'secondary','old')+btn('choose','새 카드: '+CARDS[c.incoming].name,'primary','new');if(c.kind==='toll')return '<p>'+node(game.p.pos).name+' · 통행료 '+money(c.cost)+'엽전<br>카드 사용 또는 납부를 선택하세요.</p>'+c.options.map(v=>btn('choose',v==='pay'?'통행료 납부':v==='shield'?'통행증 · 통행료 면제':'마패 탈취 · '+money(Math.floor(game.landValue(game.p.pos)*.5))+'엽전 반값 매입',v==='pay'?'secondary':'primary',v)).join('');if(c.kind==='freeze')return '<p>'+esc(game.p.name)+'의 배당 '+c.payout+'엽전<br>'+esc(p.name)+' · 동작그만 사용 시 '+Math.floor(c.payout*.5)+'엽전을 받습니다.</p>'+btn('choose','동작그만 사용','primary','use')+btn('choose','사용하지 않기','secondary','skip');if(c.kind==='invest')return '<p>팀 고을을 하나 선택하세요.<br>복귀 횟수와 관계없이 모든 단계 건물을 무료로 건설합니다.</p>'+targets(c.options,'choose');if(c.kind==='boost')return '<p>다음 도착 통행료를 두 배로!<br>우리 팀의 고을을 선택하세요.</p>'+targets(c.options,'choose');if(c.kind==='inspect')return '<p>상대 고을의 건물을 전부 매각합니다.<br>대상 고을을 선택하세요.</p>'+targets(c.options,'choose');if(c.kind==='bandit')return '<p>산적에게 반납할 카드 한 장을 고르세요.</p>'+c.options.map(i=>btn('choose',CARDS[p.cards[i]].name,'secondary',i)).join('');if(c.kind==='gamble')return `<p>한 판만 진행합니다. 윷 2배 · 모 3배 · 빽도 5배.<br>그 외에는 판돈을 잃습니다.</p><div class="bet-value"><span id="bet-number">${Math.min(bet,c.max)}</span> <small>엽전</small></div><input class="bet-input" id="bet-input" aria-label="판돈" type="range" min="${c.min}" max="${c.max}" value="${Math.min(bet,c.max)}">${powerButton('gamble','판돈을 걸고 윷 던지기')}`;break;}case'manage':return `<p>${p.out?'이번 양반은 파산했습니다.':node(p.pos).name+'에 도착했습니다.'}<br>출발점 복귀 ${p.laps||0}회 · 건설 가능 ${game.maxBuild()}단계</p>${game.canBuy()?btn('buy',node(p.pos).price+'엽전으로 고을 매입'):''}${game.canAcquire()?btn('acquire','상대 고을 매입 · '+money(game.acquirePrice())+'엽전'):''}${game.availableBuildings().map(t=>btn('build',BUILDINGS[t]+' 짓기 · '+game.buildCost(p.pos,t)+'엽전','primary',t)).join('')}${game.remaining().length?btn('continue','남은 윷 결과 선택 →','secondary'):btn('end','차례 마치기 →','secondary')}`;;}return '';}
let saleSelection=new Set();
function debtPanel(){const d=game.s.debt,p=game.p,need=d.amount-p.cash;return '<p><b>'+esc(d.label)+' · '+money(d.amount)+'엽전</b><br>현금 '+money(p.cash)+'엽전 · 부족액 '+money(need)+'엽전</p><p class="warning">'+(p.cash+game.liquidation()<d.amount?'모든 자산 매각으로도 부족합니다. '+(!p.pawnUsed?'전당포로 마지막 구제를 받거나 파산을 선택하세요.':'전당포를 이미 사용했습니다.'): '매각할 고을을 선택하세요. 건물도 함께 매각됩니다.')+'</p><div class="sale-list">'+game.saleOptions().map(o=>'<label class="sale-row"><input type="checkbox" data-sale="'+o.id+'" '+(saleSelection.has(o.id)?'checked':'')+' '+(busy?'disabled':'')+'><span>'+esc(node(o.id).name)+'<small>'+game.s.land[o.id].buildings.map(t=>BUILDINGS[t]).join(' · ')+'</small></span><b>+'+money(o.value)+'엽전</b></label>').join('')+'</div><div id="sale-summary"></div><button class="primary full" id="sell-selected" data-action="sellBatch" '+(!saleSelection.size||busy?'disabled':'')+'>선택한 고을 일괄 매각</button>'+(!p.pawnUsed?btn('pawn','전당포 · 부족액 '+money(need)+'엽전 빌리기','secondary'):'<p>전당포 사용 완료 · 대출 '+money(p.pawnDebt)+'엽전</p>')+(p.cash+game.liquidation()<d.amount?btn('bankrupt','구제를 포기하고 파산','danger'):'');}
function updateSaleSummary(){if(!game||game.s.phase!=='debt')return;const options=game.saleOptions();saleSelection=new Set([...saleSelection].filter(id=>options.some(o=>o.id===id)));const amount=[...saleSelection].reduce((v,id)=>v+game.saleValue(id),0),difference=game.p.cash+amount-game.s.debt.amount;const el=document.querySelector('#sale-summary');if(el)el.innerHTML='<b>선택 매각금 '+money(amount)+'엽전</b><br>현금 포함 '+money(game.p.cash+amount)+'엽전 · '+(difference<0?'추가 필요 '+money(-difference):'납부 후 잔액 '+money(difference))+'엽전';const button=document.querySelector('#sell-selected');if(button)button.disabled=!saleSelection.size||busy;}
function cardPanel(){let p=game.s.players.find(p=>p.uid===NET.data?.user.id)||game.actor,s=game.s;if(!p.cards.length)return '<p>아직 보유한 복주머니가 없습니다.</p>';return p.cards.map((c,i)=>`<div class="card-row"><button data-action="card" data-value="${i}" ${!NET.canAct()||p.uid!==NET.data?.user.id||busy||!game.cardUsable(c,p)?'disabled':''}><b>${CARDS[c].icon} ${CARDS[c].name}</b><br>${CARDS[c].text}</button></div>`).join('');}
function detail(){if(!selected)return '<p>보드의 고을을 눌러 소유주와 통행료를 확인하세요.</p>';let n=node(selected),l=game.s.land[selected];return `<div class="detail-box"><b>${n.name}${n.reason?' ('+esc(n.reason)+')':''} </b><br>${l?`소유주 ${l.owner===null?'없음':esc(game.s.players[l.owner].name)}<br>${esc(n.reason||'고을 정보는 추후 확정')}<br>기본 매입 ${n.price}엽전<br>건설 1/2/3단계 ${[1,2,3].map(t=>game.buildCost(n.id,t)).join(' / ')}엽전<br>${l.buildings.map(t=>BUILDINGS[t]).join(' · ')||'빈 땅'} · 통행료 ${game.toll(n.id)}엽전${l.boost?' · 장원급제 적용':''}${l.mortgageTurns?' · 통행료 수거 정지 '+l.mortgageTurns+'턴':''}`:node(selected).name+' 특수 칸'}</div>`;}
function progress(){return LINES.map((line,i)=>{let counts=[0,1].map(t=>line.filter(id=>{let l=game.s.land[id];return l.owner!==null&&game.s.players[l.owner].team===t&&l.level===3}).length);return `<div class="status-line"><span>${LINE_NAMES[i]}</span><small><span style="color:var(--team-red)">${counts[0]}</span> / <span style="color:var(--team-blue)">${counts[1]}</span> · 전체 ${line.length}</small></div>`}).join('');}
function winner(){let w=game.s.winner,ps=game.s.players.filter(p=>w.team===null||p.team===w.team);return `<div class="winner"><span class="eyebrow">A GREAT ESTATE</span><h2>${w.team===null?'공동 승리':team(w.team)+' 팀 승리'}</h2><p>${esc(w.reason)}</p>${ps.map(p=>`<img src="${img(p.character)}" alt="${esc(p.name)}">`).join('')}<p>홍단 ${money(game.teamAssets(0))} · 청단 ${money(game.teamAssets(1))}엽전</p>${NET.isHost()?'<button class="secondary full" data-net="rematch">대기실로 돌아가기</button>':''}<button class="secondary full" data-net="leave">방 나가기</button></div>`;}
function render(){if(!game)return renderSetup();let s=game.s,p=game.actor;app.innerHTML=`<div class="room-game-bar"><span>방 ${esc(NET.data?.room?.name||'')} · ${NET.data?.room?.spectator?'관전 중 · 게임 조작 불가':'참가 중'} · 관전자 ${NET.data?.room?.spectatorCount||0}명</span><button class="quiet" data-net="leave">방 나가기</button></div><div class="game-title"><div><span class="eyebrow">THE YANGBAN'S JOURNEY</span><h1>오늘도, 고을에 행운이.</h1></div><div class="turn-clock"><b id="turn-countdown"></b><small id="finish-countdown"></small></div><div class="round-pill">라운드 <b>${s.round}</b> / 20</div></div><div class="players">${s.players.map(playerPanel).join('')}</div><div class="game-layout"><section>${board()}<p class="mobile-note">특수 칸 안내는 상단 ‘놀이 안내’에서 확인하세요.</p></section><aside class="side">${s.phase==='ended'?winner():`<section class="panel ${busy?'rolling':''}"><div class="action-avatar"><img src="${img(p.character)}" alt=""><div><span class="team-label t${p.team}">${team(p.team)} 팀 · ${p.ai?'AI':'사람'}</span><h2>${esc(p.name)}</h2></div></div><img class="yut-art" src="assets/yut/yut-set.png" alt="윷 네 개, 한 개는 빽도용 별 표시"><div class="rolls">${s.rolls.map(r=>`<span class="roll-result ${r.value<0?'back':''} ${r.used?'used':''}">${r.name} <small>${r.value>0?'+':''}${r.value}</small></span>`).join('')}</div><div class="actions">${isEventPopup()?'<p>이벤트 팝업에서 선택해주세요.</p>':controls()}</div></section>`}<section class="panel"><div class="panel-head"><h3>보유 복주머니 (${(s.players.find(p=>p.uid===NET.data?.user.id)?.cards.length||0)}/1)</h3><span class="eyebrow">CARDS</span></div>${cardPanel()}</section><section class="panel"><h3>대저택 직선 완성</h3><p>홍단 / 청단의 3단계 완성 고을 수</p>${progress()}</section><section class="panel"><div class="panel-head"><h3>고을 소식</h3><span class="eyebrow">CHRONICLE</span></div><div class="logs" aria-live="polite">${s.logs.slice(0,14).map(l=>`<div class="log"><small>${l.round}R</small>${esc(l.text)}</div>`).join('')}</div></section></aside></div>${eventPopup()}${detailPopup()}<p class="footer">실시간 동기화 · 복주머니 ${s.deck.length}장 · 고을 ${Object.keys(s.land).length}개 · 소유권과 엽전은 개인별 관리</p>`;persist();scheduleAI();updateSaleSummary();updateNetClock();requestAnimationFrame(()=>{const dialog=document.querySelector('.estate-popup,.event-popup');if(dialog&&!dialog.contains(document.activeElement))dialog.querySelector('button:not(:disabled),input')?.focus();});}
function boardPicking(){return game&&(['travel','route','debt'].includes(game.s.phase)||game.s.phase==='choice'&&['invest','boost','inspect'].includes(game.s.choice.kind));}
function isEventPopup(){return game&&!boardPicking()&&!NET.data?.room?.spectator&&['notice','choice','exile','debt'].includes(game.s.phase);}
function detailPopup(){if(!selected)return '';return '<div class="detail-overlay"><section class="estate-popup" role="dialog" aria-label="고을 살펴보기"><div class="panel-head"><h3>고을 살펴보기</h3><button class="quiet" data-detail-close>닫기 ×</button></div>'+detail()+'</section></div>';}
function eventPopup(){const me=game?.s.players.find(p=>p.uid===NET.data?.user.id),key=NET.data?.room?.id+':'+game?.s.turnCount;if(game?.s.phase==='ended'&&me?.out&&gameOverSeen!==key)return '<div class="event-overlay"><section class="event-popup" role="dialog" aria-modal="true" aria-label="게임 오버"><h2>게임 오버</h2><p>'+esc(me.name)+'님이 파산했습니다.</p><button class="primary full" data-net="view-result">경기 결과 보기</button></section></div>';if(!isEventPopup())return '';let s=game.s,p=game.actor;const titles={boost:'장원급제',inspect:'암행어사',bandit:'산적출현',gamble:'놀음판',invest:'상인방의 투자',keep:'복주머니 선택',toll:'상대 고을 도착',freeze:'동작그만'};let title=s.phase==='notice'?s.notice.title:s.phase==='exile'?'유배 탈출':s.phase==='debt'?'엽전 납부':titles[s.choice.kind];return '<div class="event-overlay"><section class="event-popup" role="dialog" aria-modal="true" aria-labelledby="event-title"><span class="eyebrow">GOEUL EVENT · '+esc(p.name)+'</span><h2 id="event-title">'+esc(title)+'</h2>'+((s.phase==='exile'||s.choice?.kind==='gamble')?'<img class="yut-art" src="assets/yut/yut-set.png" alt="윷">':'')+'<div class="event-actions">'+controls()+'</div><small class="muted">'+(p.ai?'AI가 선택을 진행합니다.':'선택을 마치면 게임으로 돌아갑니다.')+'</small></section></div>';}
function scheduleAI(){}
async function act(type,value){if(!game||!NET.canAct()||busy)return;if(type==='sellBatch')value=[...saleSelection];await perform(type,value,false);}
function powerButton(action,label,value){return '<div class="power-control"><button class="primary full charge-button" data-charge="true" data-action="'+action+'" '+(value!==undefined?'data-value="'+value+'"':'')+' '+(busy?'disabled':'')+' aria-label="'+label+'"><span>'+label+'</span><small>누르고 있다가 놓으세요</small></button><div class="power-track" role="progressbar" aria-label="윷 던지기 파워" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i class="power-fill"></i></div><div class="power-readout"><span>가볍게</span><b class="power-label">0%</b><span>힘차게</span></div></div>';}
async function perform(type,value){if(!game||busy||!NET.canAct()||game.s.phase==='ended')return;if(type==='extra')value=value===true||value==='true';if(type==='card')value=Number(value);if(type==='gamble'){type='choose';value=Math.min(bet,game.s.choice.max);}const actor={...game.p},before=actor.pos,throwing=['roll','exileRoll'].includes(type)||(type==='extra'&&value)||(type==='choose'&&game.s.choice?.kind==='gamble');let generation=epoch;busy=true;render();try{const data=await NET.call('action',{type,value,power:releasedPower});const resolved=new Game(data.room.state);if(throwing)await animateThrow(releasedPower,generation);if(['use','route','travel'].includes(type)&&actor.id===resolved.p.id&&before!==resolved.p.pos){game=resolved;await animateMove(actor,before,resolved.s.lastPath||[resolved.p.pos],generation);}if(type==='build')justBuilt=resolved.p.pos;if(type==='sellBatch')saleSelection.clear();}catch(error){toast(error.message);}finally{if(generation===epoch){busy=false;applyNetState();}}}
async function animateThrow(power,generation){const anchor=document.querySelector('.event-popup .yut-art')||document.querySelector('.yut-art');if(!anchor)return;const track=document.querySelector('.power-track');track?.setAttribute('aria-valuenow',String(power));document.querySelector('.power-fill')?.style.setProperty('width',power+'%');const label=document.querySelector('.power-label');if(label)label.textContent=power+'%';const stage=document.createElement('div');stage.className='throw-stage';stage.innerHTML='<span class="throw-caption">파워 '+power+'%</span>'+Array.from({length:4},(_,i)=>'<img class="throw-stick stick-'+i+'" src="assets/yut/'+(i===3?'stick-flat-marked.png':i%2?'stick-flat.png':'stick-rounded.png')+'" alt="" style="left:'+((i*22)+3)+'%;--flight:'+Math.round(45+power*.55)+'px;--spin:'+((i%2?-1:1)*(260+power*4))+'deg">').join('');anchor.replaceWith(stage);let duration=700+power*5;for(const el of stage.querySelectorAll('img'))el.style.animationDuration=duration+'ms';await new Promise(resolve=>setTimeout(resolve,duration+80));if(generation!==epoch)return;stage.classList.add('landed');}
async function animateMove(actor,before,path,generation){const board=document.querySelector('.board');if(!board)return;board.querySelectorAll('[data-pid="'+actor.id+'"]').forEach(el=>el.style.visibility='hidden');let floating=document.createElement('div');floating.className='moving-token owner-'+actor.color+' t'+actor.team;floating.innerHTML='<img src="'+img(actor.character)+'" alt="'+esc(actor.name)+' 이동 중"><i></i>';let current=node(before);floating.style.left=current.x+'%';floating.style.top=current.y+'%';board.appendChild(floating);let duration=matchMedia('(prefers-reduced-motion: reduce)').matches?1:220;for(const id of path){if(generation!==epoch)break;const next=node(id);let anim=floating.animate([{left:current.x+'%',top:current.y+'%'},{left:next.x+'%',top:next.y+'%'}],{duration,easing:'ease-in-out'});floating.querySelector('img').animate([{transform:'translateY(0)'},{transform:'translateY(-14px)'},{transform:'translateY(0)'}],{duration,easing:'ease-in-out'});await anim.finished;floating.style.left=next.x+'%';floating.style.top=next.y+'%';current=next;}floating.remove();}
function startCharge(el){if(!game||!NET.canAct()||busy||charge)return;releasedPower=8;charge={el,type:el.dataset.action,value:el.dataset.value,start:performance.now(),power:0,generation:epoch,frame:null};el.classList.add('charging');const frame=()=>{if(!charge)return;charge.power=Math.min(100,Math.round((performance.now()-charge.start)/14));const parent=charge.el.closest('.power-control');parent?.querySelector('.power-fill')?.style.setProperty('width',charge.power+'%');const label=parent?.querySelector('.power-label');if(label)label.textContent=charge.power+'%';parent?.querySelector('.power-track')?.setAttribute('aria-valuenow',String(charge.power));charge.frame=requestAnimationFrame(frame);};frame();}
function cancelCharge(){if(!charge)return;cancelAnimationFrame(charge.frame);charge.el.classList.remove('charging');charge=null;}
function releaseCharge(){if(!charge)return;let c=charge;releasedPower=Math.max(8,c.power);cancelCharge();if(c.generation===epoch)act(c.type,c.value);}
function showPreview(index){if(!game||busy||game.s.phase!=='moves')return;hoverPreview=Number(index);document.querySelectorAll('.preview-target').forEach(el=>el.classList.remove('preview-target'));document.querySelector('.forecast')?.remove();const options=game.preview(Number(index));const svg=document.querySelector('.routes');if(!svg)return;const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.setAttribute('class','forecast');for(const option of options){document.querySelector('[data-node="'+option.at+'"]')?.classList.add('preview-target');const line=document.createElementNS('http://www.w3.org/2000/svg','polyline');line.setAttribute('points',[game.p.pos,...option.path].map(id=>node(id).x+','+node(id).y).join(' '));group.appendChild(line);}svg.appendChild(group);}
function clearPreview(){hoverPreview=null;document.querySelectorAll('.preview-target').forEach(el=>el.classList.remove('preview-target'));document.querySelector('.forecast')?.remove();}

app.addEventListener('click',e=>{let el=e.target.closest('[data-do],[data-action],[data-node],[data-char],[data-slot]');if(!el)return;if(el.dataset.do){switch(el.dataset.do){case'start':start();break;case'resume':{let state=saved();if(state){clearRun();game=new Game(state);paused=false;selected=null;document.querySelector('#reset-btn').hidden=false;render();}break}case'new':setup();break;case'pause':paused=!paused;render();break;}return;}if(!game){if(el.dataset.char!==undefined){config[activeSlot].character=Number(el.dataset.char);renderSetup();}else if(el.dataset.slot!==undefined&&!e.target.closest('input,select')){activeSlot=Number(el.dataset.slot);renderSetup();}return;}if(el.dataset.node){if(busy)return;let id=el.dataset.node;if(eligible(id)){selected=null;if(game.s.phase==='debt'){saleSelection.has(id)?saleSelection.delete(id):saleSelection.add(id);render();}else act(game.s.phase==='route'?'route':game.s.phase==='travel'?'travel':'choose',id);}else{selected=id;render();}return;}if(el.dataset.action&&!el.hasAttribute('data-charge'))act(el.dataset.action,el.dataset.value);});
app.addEventListener('change',e=>{let el=e.target;if(el.dataset.name!==undefined)config[Number(el.dataset.name)].name=el.value;if(el.dataset.control!==undefined)config[Number(el.dataset.control)].ai=el.value==='ai';if(el.dataset.team!==undefined){config[Number(el.dataset.team)].team=Number(el.value);renderSetup();}});
app.addEventListener('input',e=>{if(e.target.id==='bet-input'){bet=Number(e.target.value);document.querySelector('#bet-number').textContent=bet;}if(e.target.dataset.name!==undefined)config[Number(e.target.dataset.name)].name=e.target.value;});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.slot!==undefined){e.preventDefault();activeSlot=Number(e.target.dataset.slot);renderSetup();}});
document.querySelector('#rules-btn').onclick=()=>document.querySelector('#rules').showModal();document.querySelector('#close-rules').onclick=()=>document.querySelector('#rules').close();document.querySelector('#reset-btn').onclick=()=>{if(NET.data?.room&&confirm('방에서 나갈까요? 게임 중이면 AI가 이어받습니다.'))setup();};document.querySelector('.brand').onclick=e=>{e.preventDefault();if(!game)setup();else document.querySelector('#rules').showModal();};
let charge=null,releasedPower=45,lastPower=45,hoverPreview=null,justBuilt=null;
app.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-charge]');if(el){e.preventDefault();el.setPointerCapture?.(e.pointerId);startCharge(el);}});
document.addEventListener('pointerup',releaseCharge);document.addEventListener('pointercancel',cancelCharge);window.addEventListener('blur',cancelCharge);
app.addEventListener('keydown',e=>{const el=e.target.closest('[data-charge]');if(el&&[' ','Enter'].includes(e.key)){e.preventDefault();if(!e.repeat)startCharge(el);}});
app.addEventListener('keyup',e=>{if(e.target.closest('[data-charge]')&&[' ','Enter'].includes(e.key)){e.preventDefault();releaseCharge();}});
app.addEventListener('pointerover',e=>{const el=e.target.closest('[data-preview]');if(el)showPreview(el.dataset.preview);});
app.addEventListener('pointerout',e=>{const el=e.target.closest('[data-preview]');if(el&&!el.contains(e.relatedTarget))clearPreview();});
app.addEventListener('focusin',e=>{if(e.target.dataset.preview)showPreview(e.target.dataset.preview);});
app.addEventListener('focusout',e=>{if(e.target.dataset.preview)clearPreview();});
renderSetup();NET.init();

app.addEventListener('keydown',e=>{const modal=document.querySelector('.estate-popup,.event-popup');if(!modal||e.key!=='Tab')return;const list=[...modal.querySelectorAll('button:not(:disabled),input')];if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});

var roomDraft,gameOverSeen;
function draft(){return roomDraft||(roomDraft={nickname:sessionStorage.getItem('goeul-nickname')||'',name:'',password:'',joinRoom:'',joinPassword:''});}
function saveDraft(){for(const el of document.querySelectorAll('[data-draft]'))draft()[el.dataset.draft]=el.value;}
function renderLobby(){saveDraft();const data=NET.data,d=draft();document.querySelector('#reset-btn').hidden=true;if(!data?.user){app.innerHTML='<section class="lobby-hero"><div><span class="eyebrow">JOSEON · FOUR YANGBAN</span><h1>함께 윷을 던지고,<br><em>고을을 다스리다.</em></h1><p>네 명의 양반, 두 팀의 승부.<br>홍단과 청단으로 나뉘어 스무 라운드를 함께하세요.</p><form data-net-form="login" class="nickname-form"><label for="nickname">당신의 닉네임</label><input id="nickname" data-draft="nickname" maxlength="16" required placeholder="양반의 이름을 입력하세요" value="'+esc(d.nickname)+'"><button class="primary full">접속하기 →</button></form><p id="connection-note" class="warning"></p><small class="muted">같은 방의 사용자들과 실시간으로 플레이합니다.<br>빈자리는 AI 양반으로 채울 수 있습니다.</small></div><div class="lobby-art"><img src="'+img(2)+'" alt="호랑이 대감"><img src="'+img(0)+'" alt="쥐 마님"></div></section>';return;}
const r=data.room;if(r&&!r.state){renderWaitingRoom(r);return;}if(r?.state){applyNetState();return;}
app.innerHTML='<div class="lobby-heading"><div><span class="eyebrow">THE MEETING PLACE</span><h1>'+esc(data.user.name)+'님, 어느 고을로 떠날까요?</h1></div><button class="quiet" data-net="logout">닉네임 변경</button></div><div class="lobby-tools"><button class="primary" data-net="quick">빠른 참여 →</button><span>열린 방에 입장하며, 빈 방이 없으면 새 방을 만듭니다.</span></div><div class="lobby-columns"><section class="panel"><h2>방 만들기</h2><form data-net-form="create" class="room-form"><label>방 이름<input data-draft="name" maxlength="30" placeholder="'+esc(data.user.name)+'의 방" value="'+esc(d.name)+'"></label><label>비밀번호 <small>선택</small><input data-draft="password" type="password" maxlength="20" placeholder="비우면 공개 방" value="'+esc(d.password)+'"></label><button class="primary full">방 만들기</button></form></section><section><div class="section-title"><h2>함께할 방</h2><span>4인 · 2대2 · 20라운드</span></div><div class="room-list">'+(data.rooms.length?data.rooms.map(r=>'<article class="room-card"><div><span class="pill">'+(r.playing?'진행 중':r.locked?'비밀번호 방':'공개 방')+'</span><h3>'+esc(r.name)+'</h3><small class="muted">방 코드 '+r.id+' · '+r.count+'/4명</small></div><button class="secondary" data-net="join" data-room="'+r.id+'" '+(!r.playing&&r.count===4?'disabled':'')+'>'+(r.playing?'관전하기':'입장')+'</button></article>').join(''):'<div class="empty-room">아직 열린 방이 없습니다.<br>첫 번째 방을 만들어보세요.</div>')+'</div></section></div><p id="connection-note" class="warning"></p>'+joinPopup();}
function joinPopup(){const d=draft();if(!d.joinRoom)return '';return '<div class="event-overlay"><section class="event-popup" role="dialog" aria-modal="true" aria-label="방 비밀번호"><h2>방 비밀번호</h2><form data-net-form="join"><input data-draft="joinPassword" type="password" aria-label="방 비밀번호" maxlength="20" required value="'+esc(d.joinPassword)+'"><button class="primary full">비밀번호로 입장</button><button type="button" class="secondary full" data-net="join-cancel">취소</button></form></section></div>';}
function renderWaitingRoom(r){const me=NET.data.user.id,host=NET.isHost(),mine=r.seats.find(s=>s?.uid===me),counts=[0,1].map(t=>r.seats.filter(s=>s?.team===t).length),colorCounts=[0,0];const ready=r.seats.every(s=>s?.ready)&&counts.every(c=>c===2),colors=['red','blue','pink','sky'];
app.innerHTML='<div class="lobby-heading"><div><span class="eyebrow">ROOM '+r.id+'</span><h1>'+esc(r.name)+'</h1><p>홍단 '+counts[0]+'명 · 청단 '+counts[1]+'명 / 팀마다 두 명 · 모두 준비 후 시작</p></div><button class="quiet" data-net="leave">방 나가기</button></div><div class="slots">'+r.seats.map((p,i)=>{if(!p)return '<article class="slot empty-slot"><span class="eyebrow">자리 '+(i+1)+'</span><h3>양반을 기다리는 중</h3><p>다른 사용자가 입장하거나<br>방장이 AI를 넣을 수 있습니다.</p>'+(host?'<button class="secondary full" data-net="add-ai" data-seat="'+i+'">AI 넣기 +</button>':'')+'</article>';const tint=colors[p.team+(colorCounts[p.team]++?2:0)],editable=p.uid===me||host&&p.ai;return '<article class="slot team'+p.team+' owner-'+tint+' '+(p.uid===me?'active':'')+'"><span class="team-label t'+p.team+'">'+team(p.team)+' · '+(p.ai?'AI':p.uid===r.host?'방장':'사용자')+'</span><img src="'+img(p.character)+'" alt="'+CHARACTERS[p.character]+'"><h3>'+esc(p.name)+'</h3><span class="ready-status '+(p.ready?'ready':'')+'">'+(p.ready?'준비 완료 ✓':'준비 중')+'</span><select aria-label="자리 '+(i+1)+' 팀" data-room-team="'+i+'" '+(!editable?'disabled':'')+'><option value="0" '+(p.team===0?'selected':'')+'>홍단</option><option value="1" '+(p.team===1?'selected':'')+'>청단</option></select>'+(p.ai&&host?'<select aria-label="자리 '+(i+1)+' AI 캐릭터" data-ai-char="'+i+'">'+CHARACTERS.map((name,c)=>'<option value="'+c+'" '+(p.character===c?'selected':'')+' '+(r.seats.some(q=>q&&q!==p&&q.character===c)?'disabled':'')+'>'+name+'</option>').join('')+'</select>':'<p class="muted">'+CHARACTERS[p.character]+'</p>')+(host&&p.uid!==me?'<button class="quiet full" data-net="kick" data-seat="'+i+'">'+(p.ai?'AI 빼기':'내보내기')+'</button>':'')+'</article>';}).join('')+'</div><div class="section-title"><h2>내 캐릭터 선택</h2><span>선택을 바꾸면 준비 상태가 해제됩니다.</span></div><div class="char-grid">'+CHARACTERS.map((name,c)=>{const taken=r.seats.some(p=>p&&p.uid!==me&&p.character===c);return '<button class="char-choice '+(mine?.character===c?'selected':'')+'" data-net="character" data-character="'+c+'" '+(taken?'disabled':'')+' aria-label="'+name+' 선택'+(taken?' · 사용 중':'')+'"><img src="'+img(c)+'" alt=""><span>'+name+'</span></button>';}).join('')+'</div><div class="ready-row"><button class="'+(mine?.ready?'secondary':'primary')+'" data-net="ready">'+(mine?.ready?'준비 취소':'레디 · 준비 완료')+'</button><p>'+(!counts.every(c=>c===2)?'팀이 불균형합니다. 홍단·청단을 두 명씩 맞춰주세요.':r.seats.some(p=>!p)?'빈자리를 채워주세요.':!ready?'모든 사용자의 준비 완료를 기다립니다.':'모두 준비되었습니다. 방장이 시작할 수 있습니다.')+'</p>'+(host?'<button class="primary" data-net="start" '+(!ready?'disabled':'')+'>게임 시작 →</button>':'<span class="muted">방장이 게임을 시작합니다.</span>')+'</div><p id="connection-note" class="warning"></p>';}
async function applyNetState(){if(busy)return;const state=NET.data?.room?.state;if(!state){gameOverSeen=undefined;if(game){clearRun();game=null;selected=null;saleSelection.clear();}renderLobby();return;}const next=new Game(state),previous=game;if(previous?.s.phase!==state.phase)selected=null;if(state.phase!=='debt'||previous?.s.phase!=='debt')saleSelection.clear();const moved=previous?.s.players.find(p=>next.s.players[p.id]?.pos!==p.pos);const thrown=previous&&previous.p.id===next.p.id&&next.s.rolls.length>previous.s.rolls.length;if(previous&&(moved||thrown)&&state.phase!=='ended'){busy=true;const generation=epoch;try{render();if(thrown)await animateThrow(state.lastPower||50,generation);if(moved){const dest=next.s.players[moved.id];await animateMove(moved,moved.pos,next.s.lastPath?.at(-1)===dest.pos?next.s.lastPath:[dest.pos],generation);}}finally{busy=false;}}if(!NET.data?.room?.state){game=null;renderLobby();return;}game=new Game(NET.data.room.state);document.querySelector('#reset-btn').hidden=true;render();}
function updateNetClock(){const r=NET.data?.room;if(!r?.state)return;const remaining=Math.max(0,Math.ceil(((r.responseAt||r.deadline)-NET.now())/1000)),el=document.querySelector('#turn-countdown'),finish=document.querySelector('#finish-countdown');if(el)el.textContent=r.state.phase==='ended'?'경기 종료':remaining+'초'+(remaining===0?' · 자동 진행':'');if(finish)finish.textContent=r.endAt?'차례 자동 종료 '+Math.max(0,Math.ceil((r.endAt-NET.now())/1000))+'초':'';}
window.onNetUpdate=applyNetState;window.updateNetClock=updateNetClock;
app.addEventListener('input',e=>{if(e.target.dataset.draft)draft()[e.target.dataset.draft]=e.target.value;});
app.addEventListener('submit',async e=>{const kind=e.target.dataset.netForm;if(!kind)return;e.preventDefault();saveDraft();const button=e.target.querySelector('button');if(button)button.disabled=true;try{if(kind==='login'){await NET.login(draft().nickname);sessionStorage.setItem('goeul-nickname',draft().nickname);}if(kind==='create')await NET.call('create',{name:draft().name.trim(),password:draft().password});if(kind==='join'){await NET.call('join',{id:draft().joinRoom,password:draft().joinPassword});draft().joinRoom='';draft().joinPassword='';}}catch(error){toast(error.message);}finally{if(button?.isConnected)button.disabled=false;}});
app.addEventListener('click',async e=>{const el=e.target.closest('[data-net]');if(!el||el.disabled)return;const type=el.dataset.net,r=NET.data?.room;try{if(type==='view-result'){gameOverSeen=r.id+':'+game.s.turnCount;render();}if(type==='quick')await NET.call('quick');if(type==='join'){const room=NET.data.rooms.find(r=>r.id===el.dataset.room);if(room.locked){draft().joinRoom=room.id;renderLobby();}else await NET.call('join',{id:room.id});}if(type==='join-cancel'){draft().joinRoom='';renderLobby();}if(type==='leave'){await NET.call('leave');saleSelection.clear();}if(type==='character')await NET.call('edit',{character:Number(el.dataset.character)});if(type==='ready'){const mine=r.seats.find(s=>s?.uid===NET.data.user.id);await NET.call('ready',{ready:!mine.ready});}if(type==='add-ai')await NET.call('ai',{seat:Number(el.dataset.seat)});if(type==='kick')await NET.call('kick',{seat:Number(el.dataset.seat)});if(type==='start')await NET.call('start');if(type==='rematch')await NET.call('rematch');if(type==='logout'){await NET.call('logout');NET.token='';NET.data=null;NET.revision=-1;NET.renderKey='';sessionStorage.removeItem('goeul-session');renderLobby();}}catch(error){toast(error.message);}});
app.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.roomTeam!==undefined){const seat=Number(el.dataset.roomTeam),p=NET.data.room.seats[seat];await NET.call(p.ai?'ai-edit':'edit',{seat,team:Number(el.value)});}if(el.dataset.aiChar!==undefined)await NET.call('ai-edit',{seat:Number(el.dataset.aiChar),character:Number(el.value)});if(el.dataset.sale){el.checked?saleSelection.add(el.dataset.sale):saleSelection.delete(el.dataset.sale);render();}}catch(error){toast(error.message);applyNetState();}});

app.addEventListener('click',e=>{if(e.target.closest('[data-detail-close]')||e.target.classList.contains('detail-overlay')){selected=null;render();}});
app.addEventListener('keydown',e=>{if(e.key==='Escape'&&selected){selected=null;render();}});
